def get_local_time() -> str:
    """Return the local clock time in the original 12-hour display format."""
    return datetime.now().strftime("%I:%M:%S %p")


def creationyear(uid: str | int) -> str:
    """Estimate account creation year from the recovered UID-prefix rules."""
    value = str(uid)
    if len(value) == 15:
        prefix_groups = (
            (("1000000000", "100000000", "10000000", "1000000", "1000001",
              "1000002", "1000003", "1000004", "1000005"), "2009"),
            (("1000006", "1000007", "1000008", "1000009", "100001"), "2010"),
            (("100002", "100003"), "2011"),
            (("100004",), "2012"),
            (("100005", "100006"), "2013"),
            (("100007", "100008"), "2014"),
            (("100009",), "2015"),
            (("10001",), "2016"),
            (("10002",), "2017"),
            (("10003",), "2018"),
            (("10004",), "2019"),
            (("10005",), "2020"),
            (("10006",), "2021"),
            (("10009",), "2023"),
            (("10007", "10008"), "2022"),
        )
        for prefixes, year in prefix_groups:
            if value.startswith(prefixes):
                return year
        return ""

    if len(value) in (9, 10):
        return "2008"
    if len(value) == 8:
        return "2007"
    if len(value) == 7:
        return "2006"
    if len(value) == 14 and value.startswith("61"):
        return "2024"
    return ""


